package br.com.sussmartcare.triage.infrastructure.projection; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="processed_events") public class ProcessedEvent{@Id private UUID eventId;@Column(nullable=false)private String consumerName;@Column(nullable=false)private Instant processedAt;protected ProcessedEvent(){}public ProcessedEvent(UUID id,String c){eventId=id;consumerName=c;processedAt=Instant.now();}}
